<script>
(function () {
  var root = document.getElementById('products');
  if (!root) return;
  var cards = root.querySelectorAll('.tl-card');
  var groups = root.querySelectorAll('.tl-group');
  var chips = root.querySelectorAll('.tl-chip');
  var sizeSel = document.getElementById('tl-size');
  var priceSel = document.getElementById('tl-price');
  var countEl = document.getElementById('tl-count');
  var emptyEl = document.getElementById('tl-empty');
  var resetBtn = document.getElementById('tl-reset');
  var state = { cat: 'all', size: 'all', price: 'all' };

  function apply() {
    var range = state.price === 'all' ? null : state.price.split('-');
    var min = range ? Number(range[0]) : 0;
    var max = range ? Number(range[1]) : Infinity;
    var shown = 0;
    var i;
    for (i = 0; i < cards.length; i++) {
      var c = cards[i];
      var price = Number(c.getAttribute('data-price'));
      var sizes = (c.getAttribute('data-sizes') || '').split(' ');
      var ok = (state.cat === 'all' || c.getAttribute('data-cat') === state.cat) &&
               (state.size === 'all' || sizes.indexOf(state.size) !== -1) &&
               price >= min && price <= max;
      c.hidden = !ok;
      if (ok) shown++;
    }
    for (i = 0; i < groups.length; i++) {
      var g = groups[i];
      var n = g.querySelectorAll('.tl-card:not([hidden])').length;
      g.hidden = n === 0;
      var cnt = g.querySelector('.tl-group-count');
      if (cnt) cnt.textContent = '(' + n + ')';
    }
    if (countEl) countEl.textContent = 'Showing ' + shown + ' of ' + cards.length + ' products';
    if (emptyEl) emptyEl.hidden = shown !== 0;
  }

  for (var k = 0; k < chips.length; k++) {
    chips[k].addEventListener('click', function () {
      state.cat = this.getAttribute('data-cat');
      for (var j = 0; j < chips.length; j++) {
        chips[j].setAttribute('aria-pressed', chips[j] === this ? 'true' : 'false');
      }
      apply();
    });
  }
  if (sizeSel) sizeSel.addEventListener('change', function () { state.size = sizeSel.value; apply(); });
  if (priceSel) priceSel.addEventListener('change', function () { state.price = priceSel.value; apply(); });
  if (resetBtn) resetBtn.addEventListener('click', function () {
    state = { cat: 'all', size: 'all', price: 'all' };
    if (sizeSel) sizeSel.value = 'all';
    if (priceSel) priceSel.value = 'all';
    for (var j = 0; j < chips.length; j++) {
      chips[j].setAttribute('aria-pressed', chips[j].getAttribute('data-cat') === 'all' ? 'true' : 'false');
    }
    apply();
  });
  apply();
})();
</script>
